import {addItem,countItem,removeItem} from './inventory.js';
export const C4_STAGES=['idle','c4_crossing','c4_chains','c4_report','c4_braziers','c4_abbess','c4_prisoner','c4_egg','c4_dragon','c4_return','c4_done'];
const objectives={c4_crossing:'Поговорите с паромщиком Куртом в Чёрных заводях',c4_chains:'Разбейте три заколдованные цепи на островах',c4_report:'Вернитесь к Курту',c4_braziers:'Погасите три жаровни в Пепельном аббатстве',c4_abbess:'Победите Слепую Матерь',c4_prisoner:'Подберите лунную печать и освободите Эльзу',c4_egg:'Решите судьбу осквернённого яйца',c4_dragon:'Победите Пеплокрыла в его гнезде',c4_return:'Подберите сердце пепла и вернитесь к Воссу',c4_done:'Глава 4 завершена · восточная переправа свободна'};
export function chapterFourQuest({p,slots,world,legacy,show,close,sync,sound,reward,shop,lootMenu,stored=()=>[],bags=()=>[],voice=()=>{}}){
 let state={stage:'idle',chains:[],braziers:[],egg:null,side:'idle'};const active=()=>p.stage==='chapter_four',owned=id=>countItem(slots,id)+countItem(stored(),id)+bags().reduce((n,b)=>n+(b.items||[]).filter(i=>i.id===id).reduce((v,i)=>v+i.count,0),0);
 function flags(){world?.setStory({chapterFour:true,fourStage:state.stage,chains:[...state.chains],braziers:[...state.braziers],egg:state.egg,prisonerReady:['c4_prisoner','c4_egg','c4_dragon','c4_return','c4_done'].includes(state.stage),abbessActive:['c4_abbess','c4_prisoner','c4_egg','c4_dragon','c4_return','c4_done'].includes(state.stage),dragonActive:['c4_dragon','c4_return','c4_done'].includes(state.stage),workers:[0,1,2],powder:[0,1,2],side:'reported'})}
 function advance(stage){state.stage=stage;flags();sync();sound()}
 function begin(){p.stage='chapter_four';if(state.stage==='idle')state.stage='c4_crossing';flags();sync();sound();show('Глава 4. Пепел над водой','Восс: «Ротфельд держал восточную переправу в страхе. Теперь оттуда видят дракона. Но у драконов нет причин собирать людей в цепи — там кто-то распоряжается их страхом. Найди паромщика Курта. Ворота к заводям — в восточной части двора».');return true}
 function tick(){if(!active())return;if(state.stage==='c4_chains'&&state.chains.length===3)advance('c4_report');if(state.stage==='c4_braziers'&&state.braziers.length===3){advance('c4_abbess');show('Погасшие жаровни','Из часовни доносится женский голос: «Огонь не погас. Он лишь остался без пищи». За алтарём поднимается Слепая Матерь. Её защиту больше не питают жаровни.')}
 if(state.stage==='c4_abbess'&&world.findActor('abbess')?.hp===0)advance('c4_prisoner');if(state.stage==='c4_dragon'&&world.findActor('ashwing')?.hp===0)advance('c4_return');if(['c4_prisoner','c4_egg','c4_dragon','c4_return'].includes(state.stage)&&!owned('moon_seal'))world.ensureQuestDrop('moon_seal','abbess');if(state.stage==='c4_return'&&!owned('ash_heart'))world.ensureQuestDrop('ash_heart','ashwing');flags();world.updateUI(marker)}
 function marker(id){if(!active())return null;if(id==='c3-commander'&&state.stage==='c4_return')return {symbol:'?'};if(id==='c3-ferryman'&&['c4_crossing','c4_report'].includes(state.stage))return {symbol:state.stage==='c4_report'?'?':'!'};if(id==='c3-c4-prisoner'&&state.stage==='c4_prisoner')return {symbol:'?'};if(id==='c3-tracker')return state.side==='idle'?{symbol:'!',optional:true}:state.side==='collect'?{symbol:countItem(slots,'moon_herb')>=4?'?':'!',optional:true}:null;return null}
 function talk(n){
 if(n.id==='c3-commander'){if(state.stage==='c4_return'){const copy=slots.map(i=>i?{...i}:null),id='ring_'+(state.egg==='purify'?'dawn_':'cinder_')+p.classId;if(!removeItem(copy,'ash_heart')||!removeItem(copy,'moon_seal'))return show(n.name,'Принеси лунную печать Матери и сердце пепла Пеплокрыла. Если оставил в сундуке — забери.');if(!addItem(copy,id))return show(n.name,'Освободи ячейку для награды.');slots.splice(0,slots.length,...copy);reward(p,'c4-final','quest',2400);advance('c4_done');show(n.name,'Курт перевозит людей, Эльза жива. Ты вернул нам дорогу. Это больше, чем победа над чудовищем.\n\nМатерь выкармливала Пеплокрыла на человеческой боли. На её печати — знак старого двора Дракулы. Вампиры не просто собирают войско: они превращают саму землю в клетку. За переправой лежит Чёрная корона — крепость, куда ещё до вечной ночи перестали возвращаться послы. Но прежде людям нужен хлеб, а нашим — время собрать отряд. Возьми знак за службу. Эта ночь принадлежит живым.');return}return show(n.name,state.stage==='c4_done'?'К востоку снова уходят обозы. Дозор будет держать дорогу. До Чёрной короны одному не добраться — сперва соберём людей.':'Курт ждёт у переправы. Восточные ворота стоят у края двора, за мастерскими.')}
 if(n.id==='c3-ferryman'){if(state.stage==='c4_crossing'){advance('c4_chains');return show(n.name,'Раньше за проезд просили серебро. Потом стали просить людей. Матерь обещала, что дракон не тронет нас, пока мы отдаём каждого десятого путника. Моя сестра Эльза отказалась вести этот счёт. Её увели в аббатство.\n\nПаром держат три цепи с болотных островов. Сначала разбей их чары. Ведьмы стерегут каждое звено. Я не отправлю к ним другого человека вместо сестры.')}
 if(state.stage==='c4_report'){reward(p,'c4-chains','quest',1300);advance('c4_braziers');return show(n.name,'Цепи отпустили. Я смогу провести беженцев. Но Эльза всё ещё у Матери. Паломник видел, как три жаровни вытягивают силы из пленников и питают алтарь. Погаси их, прежде чем бросать ей вызов. Аббатство — по северным мосткам.\n\nЕсли вернёшь сестру, у меня останется кому передать этот старый паром.')}
 return show(n.name,state.stage==='c4_done'?'На том берегу пахнет мокрым деревом и хлебом. Давно не думал, что буду радоваться такому запаху.':'Паром готов. Я вывезу людей, а ты возвращай Эльзу. На мостках держись середины — под водой нет дна, на которое можно встать.',[['Припасы для дороги',()=>shop('order_supplies')],['До встречи',close]])}
 if(n.id==='c3-tracker'){if(state.side==='idle')return show(n.name,'Гарпии украли мой оберег, а ведьмы оставили мне их голоса. Каждую ночь слышу крик, даже когда птицы молчат. Нужны четыре пучка лунной травы — она остаётся там, где умирают эти твари. Поможешь?',[['Соберу травы',()=>{state.side='collect';sync();sound();close()}],['Не сейчас',close]]);if(state.side==='collect'&&countItem(slots,'moon_herb')>=4)return show(n.name,'Ты принёс травы? Дай сюда. Если крик стихнет, я снова смогу вести людей через трясину.',[['Отдать четыре пучка',()=>{const copy=slots.map(i=>i?{...i}:null);removeItem(copy,'moon_herb',4);if(!addItem(copy,'ring_reed'))return show(n.name,'Освободи ячейку для оберега.');slots.splice(0,slots.length,...copy);state.side='done';reward(p,'c4-reyna','quest',800);sync();sound();show(n.name,'Тихо… Впервые за месяц тихо. Возьми мой дорожный оберег. Он лучше послужит тебе, чем старому страху.')}],['Позже',close]]);return show(n.name,state.side==='done'?'Я выведу оставшихся беженцев к Курту. Раз уж снова могу слышать дорогу.':'Ищи лунную траву у болотных ведьм и утопцев. Четырёх пучков хватит.')}
 if(n.id==='c3-c4-prisoner'){if(state.stage==='c4_prisoner'){if(!countItem(slots,'moon_seal'))return show(n.name,'Печать Матери управляет путами. Подбери её у алтаря — без неё цепи не отпустят.');reward(p,'c4-elsa','quest',1200);advance('c4_egg');return show(n.name,'Курт прислал тебя? Значит, он всё ещё не согнулся. Я сама найду мостки, только послушай.\n\nМатерь держала яйцо дракона на алтаре. Его плач тянул Пеплокрыла к аббатству, и она кормила его той же скверной, которой пугала нас. Я видела: лунная печать может разорвать связь. Или можно уничтожить яйцо — тогда дракон останется без подпитки. Но не без ярости. Реши у алтаря. Я больше не хочу решать чужую жизнь за чужой спиной.')}
 return show(n.name,'Я пойду к брату. Ты уже сделал достаточно, чтобы я могла выбраться сама.')}
 if(n.id==='c3-c4-pilgrim')return show(n.name,'Я пришёл сюда молиться о рассвете. Матерь сказала: у луны тоже бывают голодные дети. По ночам в небе кричали драконы, а утром в трапезной становилось на одного меньше.');
 if(n.id==='c3-armorer')return show(n.name,'Чешуя дракончиков держит жар, лунная трава гасит скверну. Принесёшь шесть чешуек, четыре пучка и65золотых — выкую оружие с пепельным сердцем.',[['Изготовить оружие',()=>{const copy=slots.map(i=>i?{...i}:null);if(countItem(copy,'dragon_scale')<6||countItem(copy,'moon_herb')<4||(p.gold||0)<65)return show(n.name,'Нужно6чешуек дракона,4лунные травы и65золота.');removeItem(copy,'dragon_scale',6);removeItem(copy,'moon_herb',4);if(!addItem(copy,p.classId+'_ash'))return show(n.name,'Освободи ячейку для оружия.');slots.splice(0,slots.length,...copy);p.gold-=65;sync();show(n.name,'Готово. Оружие в сумке. Не забывай: оно держит жар, но не делает тебя неуязвимым.')}],['Открыть лавку',()=>shop('order_smith')],['До встречи',close]]);
 if(n.id==='c3-quartermaster'||n.id==='c3-doctor')return show(n.name,'Собираешься в заводи? Пополни припасы до выхода.',[['Открыть лавку',()=>shop('order_supplies')],['До встречи',close]]);
 return show(n.name,'С переправы всё чаще несёт пеплом. Когда вернутся лодки, станет ясно, остались ли за водой живые.')
 }
 function interact(){if(!active()||!world.inside)return false;const a=world.action();if(!a)return false;
 if(a.type==='npc'){voice(a.npc.woman?'villager-woman':'villager-1');talk(a.npc);return true}
 if(a.type==='travel'){if(a.to==='valden'){world.leave();sync();return true}if(a.to==='abbey'&&!['c4_braziers','c4_abbess','c4_prisoner','c4_egg','c4_dragon','c4_return','c4_done'].includes(state.stage)){show('Чёрные мостки','Поговорите с Куртом и разорвите чары трёх цепей.');return true}if(a.to==='aerie'&&!['c4_dragon','c4_return','c4_done'].includes(state.stage)){show('Тропа к гнезду','Сначала освободите Эльзу и решите судьбу яйца.');return true}world.resetCombat();const poses=a.back?{marsh:[5200,1.7,-294],abbey:[5600,1.7,-268],fortress:[4076,1.7,-164]}:null;world.enter(a.to,poses?.[a.to]?{position:poses[a.to],yaw:Math.PI,pitch:0}:undefined);flags();close();sync();return true}
 if(a.type.startsWith('c4-chain-')){if(state.stage!=='c4_chains')return true;if(!world.clearAt(a.x,a.z,12))return show('Заколдованная цепь','Ведьмы ещё удерживают чары. Победите ближайших стражей.'),true;const i=Number(a.type.slice(-1));if(!state.chains.includes(i))state.chains.push(i);flags();sync();sound();show('Лопнувшее звено','Цепи ослаблены: '+state.chains.length+' / 3. На воде слышно, как паром ударяется о причал.');return true}
 if(a.type.startsWith('c4-brazier-')){if(state.stage!=='c4_braziers')return true;if(!world.clearAt(a.x,a.z,12))return show('Пепельная жаровня','Сначала победите ближайших прислужников.'),true;const i=Number(a.type.slice(-1));if(!state.braziers.includes(i))state.braziers.push(i);flags();sync();sound();show('Погасшее пламя','Жаровни погашены: '+state.braziers.length+' / 3. Связь с алтарём слабеет.');return true}
 if(a.type==='c4-egg'){if(state.stage!=='c4_egg')return show('Осквернённое яйцо','По скорлупе пробегают тёмные жилы. Сначала разберитесь с Матерью и освободите пленницу.'),true;show('Последнее яйцо','Под скорлупой шевелится живое существо. Лунная печать может очистить связь, но Пеплокрыл сохранит часть защитной силы. Разрушение лишит его подпитки — и приведёт в ярость.',[['Очистить яйцо',()=>chooseEgg('purify')],['Уничтожить скверну вместе с яйцом',()=>chooseEgg('destroy')],['Мне нужно подумать',close]]);return true}
 if(a.type==='checkpoint'){p.checkpoint={id:'c3-'+world.mode,zone:'c3_'+world.mode,position:[a.fire.x+2.2,1.7,a.fire.z]};sync();sound();show('Контрольная точка','Этот очаг станет местом возвращения.');return true}if(a.type==='chest'){lootMenu(world.openChest(a.chest));return true}if(a.type==='c4-nest'){show('Гнездо Пеплокрыла','Обугленные ветви ещё тёплые. На камнях лежат осколки старых пут.');return true}return false;
 }
 function chooseEgg(choice){state.egg=choice;advance('c4_dragon');reward(p,'c4-egg','quest',700);show('Треск скорлупы',choice==='purify'?'Тёмные жилы гаснут. Под скорлупой ровно светится тёплый огонь. Из гнезда отвечает рёв: связь разорвана, но взрослый дракон ещё обезумел от боли. Его защита уцелела; зато Матерь больше не сможет призвать к нему выводок.':'Яйцо осыпается чёрным пеплом. За скалами взрывается яростный рёв. Пеплокрыл потерял защитную связь, но на его крик слетятся пепельные дракончики.')}
 function navigation(){if(!active())return null;const z=world.mode,s=state.stage;if(z==='pass')return [3600,-258];if(z==='quarry')return [4400,-26];if(z==='siege')return [4800,-20];if(z==='fortress')return s==='c4_done'||s==='c4_return'&&countItem(slots,'ash_heart')&&countItem(slots,'moon_seal')?[4006,-77]:[4076,-170];if(!world.inside)return legacy?.mode==='city'?[2400,-224]:legacy?.mode==='road'?[2000,-230]:legacy?.mode==='inn'?[2800,-20]:legacy?.mode==='manor'?[3200,-20]:[0,-118];let dest='marsh',point=[5192,-42];if(s==='c4_chains'){const points=[[-48,-115],[48,-170],[-46,-235]],i=[0,1,2].find(i=>!state.chains.includes(i));point=i===undefined?[5192,-42]:[5200+points[i][0],points[i][1]]}else if(s==='c4_braziers'){dest='abbey';const points=[[-55,-102],[55,-145],[-20,-218]],i=[0,1,2].find(i=>!state.braziers.includes(i));point=i===undefined?[5600,-231]:[5600+points[i][0],points[i][1]]}else if(['c4_abbess','c4_prisoner','c4_egg'].includes(s)){dest='abbey';point=s==='c4_abbess'?[5600,-231]:s==='c4_prisoner'&&!countItem(slots,'moon_seal')?[5600,-231]:s==='c4_prisoner'?[5623,-237]:[5600,-247]}else if(s==='c4_return'&&!countItem(slots,'moon_seal')){dest='abbey';point=[5600,-231]}else if(s==='c4_dragon'||s==='c4_return'&&!countItem(slots,'ash_heart')){dest='aerie';point=[6000,-155]}else if(['c4_return','c4_done'].includes(s)){dest='fortress';point=[4006,-77]}if(z===dest)return point;if(z==='marsh')return dest==='fortress'?[5200,-20]:[5200,-304];if(z==='abbey')return dest==='aerie'?[5600,-278]:[5600,-20];if(z==='aerie')return [6000,-20];return [4076,-170]}
 return {begin,active,flags,tick,interact,marker,navigation,objective:()=>active()?'Пепел над водой\n'+objectives[state.stage]+(state.stage==='c4_chains'?' ('+state.chains.length+' / 3)':state.stage==='c4_braziers'?' ('+state.braziers.length+' / 3)':''):null,optional:()=>active()&&state.side==='collect'?'Голоса трясины: принесите Рейне лунную траву ('+Math.min(4,countItem(slots,'moon_herb'))+' / 4)':'',snapshot:()=>({...state,chains:[...state.chains],braziers:[...state.braziers]}),restore(s){state={stage:'idle',chains:[],braziers:[],egg:null,side:'idle',...s};if(active())flags()},get state(){return state}};
}
